// Generated by `bun run gen:client` in the Sora repository. Do not edit by hand.
// Find tools without loading every definition: names first, then the file you need.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export interface CatalogEntry {
  name: string;
  fn: string;
  category: string;
  description: string;
  keywords: string[];
  method: string;
  path: string;
  /** Path of the generated module, relative to this directory. */
  file: string;
}

export type Detail = 'names' | 'summary';

let catalog: CatalogEntry[] | undefined;
const load = (): CatalogEntry[] => (catalog ??= JSON.parse(readFileSync(fileURLToPath(new URL('./catalog.json', import.meta.url)), 'utf8')) as CatalogEntry[]);

/** Case-insensitive search over name, category, description and keywords. All words must match. */
export function searchTools(query: string, detail: Detail = 'summary'): Array<Pick<CatalogEntry, 'name' | 'fn' | 'category' | 'file'> & Partial<CatalogEntry>> {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  return load()
    .filter((tool) => {
      const haystack = [tool.name, tool.category, tool.description, ...tool.keywords].join(' ').toLowerCase();
      return words.every((word) => haystack.includes(word));
    })
    .map((tool) => (detail === 'names' ? { name: tool.name, fn: tool.fn, category: tool.category, file: tool.file } : tool));
}
